function kInversePairs(n, k) {
  const MOD = 1000000007;
  let prev = new Array(k + 1).fill(0);
  prev[0] = 1;

  for (let i = 2; i <= n; i++) {
    const curr = new Array(k + 1).fill(0);
    let window = 0;
    for (let j = 0; j <= k; j++) {
      window = (window + prev[j]) % MOD;
      if (j >= i) {
        window = (window - prev[j - i] + MOD) % MOD;
      }
      curr[j] = window;
    }
    prev = curr;
  }
  return prev[k];
}

