function kInversePairs(n, k) {
  // Direct recurrence without any running sum: placing the largest value m among
  // m slots adds between 0 and m - 1 inverse pairs, so add up every choice.
  const MOD = 1000000007;
  let ways = [1];
  for (let m = 2; m <= n; m++) {
    const grown = [];
    for (let j = 0; j <= k; j++) {
      let total = 0;
      for (let added = 0; added < m && added <= j; added++) total += ways[j - added] ?? 0;
      grown.push(total % MOD);
    }
    ways = grown;
  }
  return ways[k] ?? 0;
}

