function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    if (rand() < 0.4) return [1000, 1000];
    return [700 + pick(301), 700 + pick(301)];
  }
  const n = 1 + pick(8);
  const most = n * (n - 1) / 2;
  // Sometimes ask for more inverse pairs than are possible, so the answer is 0.
  const k = rand() < 0.15 ? most + 1 + pick(5) : pick(most + 1);
  return [n, k];
}
